#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <stdexcept>
#include <iomanip>
using namespace std;

class Student {
public:
    Student(string name, double grade, int age, int roll)
        : name(name), grade(grade), age(age), roll(roll) {}

    string getName() const { return name; }
    double getGrade() const { return grade; }
    int getAge() const { return age; }
    int getRoll() const { return roll; }

private:
    string name;
    double grade;
    int age;
    int roll;
};

ostream& operator<<(ostream& os, const Student& s) {
    os << s.getName() << "(grade=" << fixed << setprecision(1) << s.getGrade()
       << ", age=" << s.getAge() << ", roll=" << s.getRoll() << ")";
    return os;
}

class StudentSorterNaive {
public:
    void sortStudents(vector<Student>& students, const string& type) {
        if (type == "NAME") {
            cout << "Sorting by Name..." << endl;
            sort(students.begin(), students.end(), [](const Student& a, const Student& b) {
                return a.getName() < b.getName();
            });
        } else if (type == "GRADE") {
            cout << "Sorting by Grade..." << endl;
            sort(students.begin(), students.end(), [](const Student& a, const Student& b) {
                return a.getGrade() > b.getGrade();
            });
        } else if (type == "AGE") {
            cout << "Sorting by Age..." << endl;
            sort(students.begin(), students.end(), [](const Student& a, const Student& b) {
                return a.getAge() < b.getAge();
            });
        } else if (type == "ROLL") {
            cout << "Sorting by Roll Number..." << endl;
            sort(students.begin(), students.end(), [](const Student& a, const Student& b) {
                return a.getRoll() < b.getRoll();
            });
        } else {
            throw invalid_argument("Unknown sort type: " + type);
        }
    }
};

int main() {
    vector<Student> students = {
        Student("Charlie", 88.5, 21, 3),
        Student("Alice", 92.0, 19, 1),
        Student("Bob", 75.0, 20, 2)
    };

    StudentSorterNaive sorter;
    sorter.sortStudents(students, "NAME");
    for (const auto& s : students) cout << s << " ";
    cout << endl;
    return 0;
}

