#include <iostream>
#include <memory>
#include <iomanip>
using namespace std;

class DiscountStrategy {
public:
    virtual double apply(double price) = 0;
    virtual ~DiscountStrategy() = default;
};

class NoDiscount : public DiscountStrategy {
public:
    double apply(double price) override {
        cout << "No discount applied." << endl;
        return price;
    }
};

class StudentDiscount : public DiscountStrategy {
public:
    double apply(double price) override {
        cout << "Student discount: 20% off." << endl;
        return price * 0.80;
    }
};

class MemberDiscount : public DiscountStrategy {
public:
    double apply(double price) override {
        cout << "Member discount: 30% off." << endl;
        return price * 0.70;
    }
};

class SeasonalDiscount : public DiscountStrategy {
public:
    double apply(double price) override {
        cout << "Seasonal sale: 50% off." << endl;
        return price * 0.50;
    }
};

class BillingService {
public:
    explicit BillingService(shared_ptr<DiscountStrategy> strategy) : strategy(strategy) {}

    void setStrategy(shared_ptr<DiscountStrategy> newStrategy) {
        strategy = newStrategy;
    }

    double bill(double price) {
        double finalPrice = strategy->apply(price);
        cout << "Final price: $" << fixed << setprecision(1) << finalPrice << endl;
        return finalPrice;
    }

private:
    shared_ptr<DiscountStrategy> strategy;
};

int main() {
