    billing.setStrategy(make_shared<MemberDiscount>());
    billing.bill(100.00);

    cout << "\n--- Seasonal Sale ---" << endl;
    billing.setStrategy(make_shared<SeasonalDiscount>());
    billing.bill(100.00);

    return 0;
}
